INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N037-03','CN0284','S037-02','厂区搬迁和现有水站','p83、103–105','光大路原分子筛1000、活性氧化铝800t/a，2013历史分子筛8000，2023五月搬迁淘汰后约1000。历史384m³/d；申报表列监测最高值，不是实际流量或当前值。','WEB_PRIMARY','公开正文/表格摘要，非原件归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N037-04','CN0285','S037-02','已建产线及水站','p83、93、103–104','楚华支路5600原项目，6000扩建2023年7–8月验收投产；结构改造能力不变。600m³/d站，厂区排口最高值。','WEB_PRIMARY','公开正文/表格摘要，非原件归档','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N037-05','CN0285','S037-02','集团环保资本及费用（不可分配到单厂）','p105截图','全发行人2020/21/22/2023H1环保投资20.85/78.80/160.04/244.71万元；环保成本24.59/108.75/48.71/139.86万元，含清运、咨询检测等。2021偏高因锂分子筛离子交换碱性水中和耗材多。非逐厂废水成本；只存一次集团范围，不计经济表逐厂记录。','WEB_PRIMARY','公开正文/表格摘要，非原件归档','2026-11-28');
