INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N037-06','CN0209','S037-02','募投设计RO与前处理','p83、93、106–107；106截图','青环审2023-17，青岛平度新河淄河路北丽水路南；石灰纯碱混凝澄清、Cu/Al沉淀，曝气预氧化过滤Mn，其他高盐采用RO满足生产用水。原文未披露各级连接或浓水去向。800万元环保设施投资估算主要用于污水站等，不是污水站专款，存摘要不计逐厂水处理金额。2024公开转让材料仍为在建，2026实际未核。','WEB_PRIMARY','公开正文/表格摘要，非原件归档','2026-11-28');
